	Dangerous calls:
	- (sent,None) = to.call{value: amount}() (src/FeeCollector.sol#68)","rule":"arbitrary-send-eth","severity":"High (confidence Medium)"}],"code":[{"path":"src/FeeCollector.sol","source":"    function _send(address payable to, uint256 amount) private {
        if (to == address(0)) revert ZeroAddress();
        uint256 available = address(this).balance;
        if (amount > available) revert InsufficientFunds(amount, available);
        totalPaidOut += amount;
        (bool sent,) = to.call{value: amount}("");
        if (!sent) revert TransferFailed();
        emit PaidOut(to, amount);
    }"}]}}
